#!/usr/bin/env python3
"""Generate a credential-free live dashboard directory; never reads account data."""
from pathlib import Path
from html import escape
import base64
root = Path(__file__).resolve().parent.parent
origin = 'https://erp.eurosuitsmfg.in'
portals = [('Super Admin','admin'),('Managing Director','md'),('Management / CEO','management'),('Finance Head','finance'),('Finance & Accounts','accounts'),('Marketing & Merchandising','merchandising'),('Planning','planning'),('Development & CAD','cad'),('Sourcing','sourcing'),('Inventory & Stores','stores'),('Sampling','sampling'),('Cutting','cutting'),('Sewing Production','sewing'),('Finishing','finishing'),('Quality','quality'),('Warehouse','warehouse'),('Developer · owner access','developer')]
logo = 'data:image/png;base64,' + base64.b64encode((root/'frontend/static/logo.png').read_bytes()).decode()
cards = ''.join(f'<a class="card" href="{origin}/{slug}" target="_blank" rel="noopener"><span>{escape(name)}</span><small>Open dashboard &rarr;</small></a>' for name,slug in portals)
page = '''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="referrer" content="no-referrer"><title>Euro Suits · Live dashboard guide</title><style>
*{box-sizing:border-box}body{margin:0;background:#f1f5f4;color:#172b3e;font:16px/1.6 system-ui,sans-serif}header{background:#172b3e;color:white;padding:34px max(24px,calc((100vw - 1080px)/2));display:flex;gap:22px;align-items:center;border-bottom:4px solid #b69b68}header img{width:76px;height:76px;border-radius:12px}h1{font-size:30px;line-height:1.2;margin:0 0 8px}header p{margin:0;color:#dce6ec}main{max-width:1130px;margin:auto;padding:28px 24px}section{background:white;padding:26px;border:1px solid #d6e2df;border-radius:14px;margin-bottom:24px}h2{font-size:22px;margin:0 0 12px}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:14px}.card{display:block;padding:20px;border:1px solid #c8dad5;border-radius:10px;background:#edf5f2;color:#172b3e;text-decoration:none;font-weight:750}.card:hover,.card:focus-visible{background:#dbece6;outline:2px solid #17675e;outline-offset:2px}small{display:block;color:#17675e;margin-top:8px;font-size:14px}a{color:#17675e;font-weight:700}li{margin:8px 0}.muted{color:#526574}footer{text-align:center;padding:0 24px 28px;color:#526574}strong{font-weight:750}@media(max-width:500px){header{padding:24px;align-items:flex-start}header img{width:54px;height:54px}h1{font-size:24px}section{padding:20px}}
</style></head><body><header><img src="LOGO" alt="Euro Suits logo"><div><h1>Live dashboard guide</h1><p>Euro Suits · Your daily workspace</p></div></header><main><section><h2>Sign in to your workspace</h2><ol><li>Choose the dashboard assigned to you below.</li><li>Enter the user ID and password provided privately by your administrator or in your welcome email.</li><li>Complete email verification if enabled for your account.</li></ol><p class="muted">Each link opens the live ERP. Your company, responsibilities and available features are controlled by your administrator. A dashboard link does not grant extra access.</p><p><a href="ORIGIN">Open Euro Suits ERP</a></p></section><section><h2>Department dashboards</h2><div class="grid">CARDS</div></section><section><h2>Administrator: welcome a new user</h2><ol><li>Open <a href="ORIGIN/admin/users">User access</a> and choose Add user.</li><li>Enter the employee’s name, email address, mobile number with country code, user ID and initial password.</li><li>Select their designation, company, reporting manager and permitted responsibilities. Assign teams, lines or orders where required.</li><li>Save once. The confirmation reports whether the welcome email was accepted for delivery.</li></ol><p>The welcome email contains the assigned role, responsibilities and private sign-in details. If delivery fails, check the email issue report before taking further action; the account has already been created.</p></section><section><h2>Create and assign a team</h2><p>In User access, open Teams and add a team for the appropriate company. Then edit the employee’s access, choose the team-based scope and assign the relevant teams. Save the changes. Only an authorized administrator can change these assignments.</p><h2>Need help?</h2><p>Contact your administrator for missing features, account changes or sign-in assistance. Use your assigned account and keep its sign-in details private.</p></section></main><footer>EURO SUITS · Precision in every detail.</footer></body></html>'''.replace('LOGO',logo).replace('CARDS',cards).replace('ORIGIN',origin)
for path in [root/'testing/private/Euro-Suits-Testing-Guide.html',root/'testing/private/Euro-Suits-Live-Guide.html',root/'frontend/static/guide.html']:
    path.parent.mkdir(parents=True,exist_ok=True)
    path.write_text(page)
print('Generated three credential-free live guides.')
